import{_ as e,b as d,e as a,a8 as o}from"./chunks/framework.CumEd6mW.js";const O=JSON.parse('{"title":"Layer Option Bits","description":"","frontmatter":{"layout":"doc","docType":"api","unit":"GR32_Layers","entity":"Layer Option Bits","kind":"Constant","aliases":["LOB_VISIBLE","LOB_GDI_OVERLAY","LOB_MOUSE_EVENTS","LOB_NO_UPDATE","LOB_NO_CAPTURE","LOB_INVALID","LOB_FORCE_UPDATE","LOB_RESERVED_24","LOB_RESERVED_MASK"],"summary":"Bitmask flags controlling visibility, update behavior, mouse interaction, and repaint options for layers.","title":"Layer Option Bits","date":1788823476000,"authors":[],"tags":[],"head":[]},"headers":[],"relativePath":"api/GR32_Layers/Layer Option Bits.md","filePath":"api/GR32_Layers/Constants/Layer Option Bits.md","lastUpdated":1788823476000,"timestamp":1788823476000,"datetime":"2026-09-07T23:24:36.000Z","contributors":[]}'),r={name:"api/GR32_Layers/Layer Option Bits.md"};function i(s,t,n,c,l,_){return d(),a("div",null,[...t[0]||(t[0]=[o('<h2 id="description" tabindex="-1">Description <a class="header-anchor" href="#description" aria-label="Permalink to &quot;Description&quot;">​</a></h2><p><code>Layer Option Bits</code> (<code>LOB_*</code>) define bitwise flags used in <code>TCustomLayer.LayerOptions</code> to control visibility, repainting, overlay drawing, and mouse message capture behavior.</p><h2 id="constants-table" tabindex="-1">Constants Table <a class="header-anchor" href="#constants-table" aria-label="Permalink to &quot;Constants Table&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Constant</th><th>Value</th><th>Description</th></tr></thead><tbody><tr><td><code>LOB_VISIBLE</code></td><td><code>$80000000</code></td><td>Controls layer visibility. When set, the layer is rendered during paint cycles.</td></tr><tr><td><code>LOB_GDI_OVERLAY</code></td><td><code>$40000000</code></td><td>Indicates that the layer performs drawing when its owner control draws GDI overlays.</td></tr><tr><td><code>LOB_MOUSE_EVENTS</code></td><td><code>$20000000</code></td><td>Specifies whether the layer responds to mouse messages and hit testing.</td></tr><tr><td><code>LOB_NO_UPDATE</code></td><td><code>$10000000</code></td><td>Disables automatic repainting when layer location or properties change.</td></tr><tr><td><code>LOB_NO_CAPTURE</code></td><td><code>$08000000</code></td><td>Overrides automatic mouse message capturing when the left mouse button is pressed over the layer. Has no effect if <code>LOB_MOUSE_EVENTS</code> is cleared.</td></tr><tr><td><code>LOB_INVALID</code></td><td><code>$04000000</code></td><td>Used internally by the repaint optimizer to mark invalidated layer areas.</td></tr><tr><td><code>LOB_FORCE_UPDATE</code></td><td><code>$02000000</code></td><td>Used internally to force an area repaint when a layer is being hidden.</td></tr><tr><td><code>LOB_RESERVED_24</code></td><td><code>$01000000</code></td><td>Reserved bit.</td></tr><tr><td><code>LOB_RESERVED_MASK</code></td><td><code>$FF000000</code></td><td>Bitmask covering all system and option bit flags (bits 24..31).</td></tr></tbody></table>',4)])])}const h=e(r,[["render",i]]);export{O as __pageData,h as default};
